(() => {
'use strict';
const mount=()=>{
 const host=document.querySelector('#auxtho-workflow');if(!host||document.querySelector('#auxtho-network'))return;
 const ko=document.documentElement.lang.startsWith('ko'),t=(k,e)=>ko?k:e;
 const section=document.createElement('section');section.id='auxtho-network';section.className='an-future';section.setAttribute('aria-labelledby','an-title');
 section.innerHTML=`<div class="an-wrap"><div class="an-top"><span>AUXTHO / CONNECTED DOCUMENT HISTORY</span><span class="an-status">${t('장기 개발 방향','LONG-TERM DIRECTION')}</span></div><div class="an-heading"><h2 id="an-title">${t('다른 기관에 전달된 뒤에도,<br> 이어지는 검토·승인 이력','Review and approval history,<br> even after a document is shared')}</h2><p>${t('누가 만들고, 어디로 전달하고, 어떤 근거로 바꿨는지.<br> 문서를 주고받은 뒤의 판단까지 연결하는 구조를 지향합니다.','Who created it, where it went, and why it changed.<br> Our goal is to keep its decision history connected after it is shared.')}</p></div>
 <aside class="an-brief" aria-label="${t('장기 방향의 핵심과 범위','Long-term direction overview')}"><dl><div><dt>${t('기존 업무의 문제','THE WORK PROBLEM')}</dt><dd>${t('기관을 건너간 문서의 변경·승인 경위를 다시 모아야 합니다.','Changes and approvals must be pieced together after a document crosses organisations.')}</dd></div><div><dt>${t('Auxtho의 개발 방향','AUXTHO’S DIRECTION')}</dt><dd>${t('공통 원본과 기관별 전달·수정·승인 이력을 잇는 구조를 지향합니다.','We aim to connect a shared original to each organisation’s delivery, revision and approval history.')}</dd></div><div><dt>${t('사례의 범위','SCOPE OF THIS EXAMPLE')}</dt><dd>${t('가상 은행 A·B·C로 설명하는 장기 개발 방향입니다.','A long-term direction illustrated with fictional banks A, B and C.')}</dd></div></dl></aside><div class="an-origin"><div class="an-bank">A</div><div><span>${t('공통 원본 · 은행 A','SHARED ORIGIN · BANK A')}</span><h3>${t('AI 초안에서 담당자의 승인까지','From an AI draft to an authorised person’s approval')}</h3><p>${t('담당자 작성 → 근거·Policy Pack 확인 → 지정 승인자 승인 → 원본 v1 전달','Author prepares a draft → evidence and Policy Pack review → authorised approval → original v1 delivered')}</p></div><span class="an-doc">DOC-024 · v1</span></div>
 <div class="an-fork"><span>${t('같은 원본에서, 수신 기관별 전달·검토 이력이 나뉩니다.','One shared original. Separate delivery and review histories for each recipient.')}</span></div>
 <div class="an-branches" role="group" aria-label="${t('기관별 전달 경로 선택','Choose a recipient branch')}"><button type="button" data-an-branch="B" aria-pressed="true" aria-controls="an-record"><span class="an-branch-label">${t('전달 경로 01','DELIVERY BRANCH 01')}</span><strong>${t('은행 A → 은행 B','BANK A → BANK B')}</strong><span>${t('수신 확인 → 조건 수정 → 새 버전 승인','Receipt confirmed → terms revised → new version approved')}</span><small>v1 → B-v2 <i aria-hidden="true">↗</i></small></button><button type="button" data-an-branch="C" aria-pressed="false" aria-controls="an-record"><span class="an-branch-label">${t('전달 경로 02','DELIVERY BRANCH 02')}</span><strong>${t('은행 A → 은행 C','BANK A → BANK C')}</strong><span>${t('수신 확인 → 원본 검토 → 원본 버전 승인','Receipt confirmed → original reviewed → original version approved')}</span><small>v1 · ${t('내용 유지','CONTENT UNCHANGED')} <i aria-hidden="true">↗</i></small></button></div>
 <div id="an-record" class="an-record" aria-live="polite"></div>
 <div class="an-lookup"><div><span>03 / ${t('나중에 질문이나 문제가 생기면','WHEN A QUESTION OR ISSUE ARISES')}</span><h3>${t('문서를 검토하고 승인한 근거를 확인합니다','See the evidence behind the review and approval')}</h3><p>${t('문서의 QR이나 조회 화면으로 해당 기록을 열어, 권한 범위 안에서 원본·판단·전달 이력을 확인하는 흐름입니다.','Open the record through the document’s QR code or a lookup screen, then view the original sources, decisions and delivery history within your access permissions.')}</p></div><div class="an-lookup-actions"><button type="button" data-an-entry="qr" aria-expanded="false" aria-controls="an-evidence">${t('문서의 QR로 기록 확인','View the record via the document’s QR code')} ↗</button><button type="button" data-an-entry="console" aria-expanded="false" aria-controls="an-evidence">${t('내부 운영 콘솔 조회 예시','Internal Console lookup example')} ↗</button><small>${t('조회 흐름 시연 · 실제 QR/Console 연결 아님','LOOKUP ILLUSTRATION · NO LIVE QR / CONSOLE CONNECTION')}</small></div></div>
 <div id="an-evidence" class="an-evidence" hidden></div><p class="an-role-note">${t('현재 Console은 Auxtho 내부의 운영·조사 화면입니다. 위 사례는 향후 기관별 권한에 따른 조회 흐름을 설명합니다.','Console currently serves Auxtho’s internal operations and investigation. The example above illustrates a future lookup flow governed by each organisation’s access permissions.')}</p><p class="an-note">${t('가상 기관·문서로 설명한 장기 목표 구조입니다. 기관 간 연동이 완료되었거나 실제 고객이 사용하는 기능을 뜻하지 않습니다. 연결·기록된 범위에서 권한에 따라 확인하며, Replay는 기록된 과정을 재구성하는 조회입니다.','A long-term target illustrated with fictional organisations and documents, not a completed inter-organisation integration or a customer deployment. Inspection is limited to connected records and access permissions. Replay reconstructs recorded steps for inspection.')}</p></div>`;
 document.querySelector('#main > #contact').before(section);let branch='B',entry=null;
 const render=()=>{
 const revised=branch==='B';
 section.querySelectorAll('[data-an-branch]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.anBranch===branch)));
 section.querySelector('#an-record').innerHTML=`<div class="an-record-head"><b>${t('은행','BANK')} ${branch} / ${t('연결되는 기록 · 가상 사례','CONNECTED RECORDS · ILLUSTRATION')}</b><span>${revised?'B-v2':'v1'}</span></div><ol><li><span>01</span><div><b>${t('누가 받았는가','Who received it')}</b><p>${branch==='B'?t('은행 B 접수 담당자가 은행 A의 승인본 v1을 받았음을 확인합니다.','Bank B’s receiving officer confirms receipt of Bank A’s approved v1.'):t('은행 C 접수 담당자가 은행 A의 승인본 v1을 받았음을 확인합니다.','Bank C’s receiving officer confirms receipt of Bank A’s approved v1.')}</p></div></li><li><span>02</span><div><b>${revised?t('누가, 왜 바꿨는가','Who changed it, and why'):t('무엇을 검토했는가','What was reviewed')}</b><p>${revised?t('은행 B 담당자가 보증 조건을 수정하고, 보완 증빙과 적용한 내부 규칙의 버전을 수정 사유에 연결합니다.','A Bank B reviewer revises the guarantee terms and records the supporting evidence and the version of the internal rules used.'):t('은행 C 담당자가 원본의 조건과 근거를 검토합니다. 문서 내용은 v1을 유지합니다.','A Bank C reviewer checks the original terms and evidence. The document content remains at v1.')}</p></div></li><li><span>03</span><div><b>${t('누가 어떤 버전을 승인했는가','Who approved which version')}</b><p>${revised?t('은행 B 지정 승인자가 B-v2를 별도로 승인합니다. 은행 A의 원본 v1 승인 이력도 보존합니다.','Bank B’s authorised approver separately approves B-v2. Bank A’s approval of the original v1 remains recorded.'):t('은행 C 지정 승인자가 원본 v1을 승인합니다. 은행 B의 수정·승인 이력은 B 경로에 별도로 남습니다.','Bank C’s authorised approver approves the original v1. Bank B’s revisions and approval remain recorded on its separate branch.')}</p></div></li></ol><p class="an-version-note">${t('내용이 바뀌면 새 문서 버전으로 검토·승인합니다. 같은 원본을 여러 곳에 보낸 경우에는 전달·승인 이력을 각각 구분합니다.','Changed content is reviewed and approved as a new document version. Deliveries of the same original retain separate delivery and approval histories.')}</p>`;
 if(entry)show(entry);
 };
 const show=(method)=>{entry=method;section.querySelectorAll('[data-an-entry]').forEach(b=>b.setAttribute('aria-expanded',String(b.dataset.anEntry===method)));const panel=section.querySelector('#an-evidence');panel.hidden=false;panel.innerHTML=`<span class="an-branch-label">${method==='qr'?t('문서 QR 진입 · 시연','DOCUMENT QR ENTRY · ILLUSTRATION'):t('Console 기록 조회 · 시연','CONSOLE RECORD LOOKUP · ILLUSTRATION')} / ${t('은행','BANK')} ${branch}</span><h4>${t('이 판단에 연결된 기록','The records behind this decision')}</h4><div class="an-evidence-grid">${[[t('원본과 문서 버전','Original document & versions'),branch==='B'?'v1 → B-v2':'v1'],[t('근거와 적용 규칙','Evidence & applied rules'),t('원문 · Policy Pack 버전 · 수정 사유','Sources · Policy Pack version · change reasons')],[t('사람의 판단','Human decisions'),t('작성자 · 검토자 · 승인자 · 결정 시점','Author · reviewer · approver · decision time')],[t('전달과 이후 이력','Delivery & subsequent history'),`A → ${branch} · ${t('수신 확인 · 버전별 기록','receipt confirmation · version history')}`]].map(([a,b])=>`<div><span>${a}</span><b>${b}</b></div>`).join('')}</div><p>${t('Replay / 포렌식 조회에서는 기록된 순서와 근거를 재구성하는 구조를 지향합니다. 조회로 지급·전송 같은 실제 행동을 다시 실행하지 않습니다.','Replay / forensic inspection is intended to reconstruct the recorded sequence and evidence. Inspection does not repeat real actions such as payments or deliveries.')}</p>`;};
 section.querySelectorAll('[data-an-branch]').forEach(b=>b.addEventListener('click',()=>{branch=b.dataset.anBranch;render();}));section.querySelectorAll('[data-an-entry]').forEach(b=>b.addEventListener('click',()=>show(b.dataset.anEntry)));render();
 if(location.hash==='#auxtho-network')requestAnimationFrame(()=>section.scrollIntoView());
};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',mount,{once:true});else mount();
})();
